"""Remove Nth Node From End of List — gap of n between two pointers.

A sentinel in front makes removing the head no different from any other node.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def removeNthFromEnd(self, head, n: int):
        sentinel = ListNode(0, head)
        lead = lag = sentinel
        for _ in range(n):
            lead = lead.next
        while lead.next:
            lead = lead.next
            lag = lag.next
        lag.next = lag.next.next
        return sentinel.next
